export const messages = {
  pl: { ...common.pl, ...pages.pl },
  en: { ...common.en, ...pages.en },
  no: { ...common.no, ...pages.no },
}

const queryLocale = typeof window !== 'undefined' ? new URLSearchParams(window.location.search).get('lang') : null
const storedLocale = typeof window !== 'undefined' ? window.localStorage.getItem('investra-locale') : null
const initialLocale = [queryLocale, storedLocale].find((code) => languages.some((language) => language.code === code)) || 'pl'
export const locale = ref(initialLocale)

export function setLocale(code) {
  if (!languages.some((language) => language.code === code)) return
  locale.value = code
  if (typeof window !== 'undefined') {
    const url = new URL(window.location.href)
    url.searchParams.set('lang', code)
    window.history.replaceState({}, '', url)
  }
}

export function useI18n() {
  return {
    locale,
    languages,
    setLocale,
    copy: computed(() => messages[locale.value]),
  }
}

watch(locale, (code) => {
  if (typeof window !== 'undefined') window.localStorage.setItem('investra-locale', code)
  if (typeof document !== 'undefined') document.documentElement.lang = code === 'no' ? 'nb' : code
}, { immediate: true })
